				if (a == b) continue;
				x = ((x >> shift) & ~std::uint32_t(3)) | digit;
				l = middle[d][digit] + a;
				r = middle[d][digit] + b;
				for (++d; d < levels; ++d) {
					auto step = route(l, r, Previous ? r - l - 1 : 0, d);
					x = (x << 2) | step.digit;
					l = middle[d][step.digit] + step.a;
					r = middle[d][step.digit] + step.b;
