import fcntl
import json
import os
from pathlib import Path
import random
import statistics
import subprocess
import tempfile

root = Path.cwd()
source = subprocess.check_output(['git', 'show', '523956f:data_structure/wavelet_matrix.hpp'], text=True)
variants = {'before': source}
for size in []:
    variants['scan' + str(size)] = source.replace('end - start <= 16', 'end - start <= ' + str(size))
search = '''
		if (CONDITION) {
			int a = 0, b = 0, length = end - start;
			while (length > 1) {
				int half = length / 2;
				a += (positions[start + a + half] < l) * half;
				b += (positions[start + b + half] < r) * half;
				length -= half;
			}
			return b - a + (positions[start + b] < r) - (positions[start + a] < l);
		}
'''
for name, condition in [('binary5', 'values.size() > 256'), ('binary1024', 'values.size() >= 1024')]:
    variants[name] = source.replace('\n\t\tauto [a, b] = interval(l, r, c);', search.replace('CONDITION', condition) + '\n\t\tauto [a, b] = interval(l, r, c);')
variants['std'] = source.replace('\n\t\tauto [a, b] = interval(l, r, c);', '\n\t\treturn std::lower_bound(positions.begin() + start, positions.begin() + end, r) - std::lower_bound(positions.begin() + start, positions.begin() + end, l);\n\t\tauto [a, b] = interval(l, r, c);')
os.sched_setaffinity(0, {2})
lock = open('/tmp/cp-wm-opt.lock', 'w')
flags = ['-std=c++23', '-O2', '-march=native', '-ftrivial-auto-var-init=zero', '-DATCODER', '-DONLINE_JUDGE']
report = dict(baseline='523956f', flags=flags, sources=variants, results=[])
rng = random.Random(20261019)
with tempfile.TemporaryDirectory(prefix='wm-count-') as tmp:
    tmp = Path(tmp)
    binaries = {}
    for name, code in variants.items():
        header = tmp / (name + '.hpp')
        header.write_text(code.replace('../components/quad_bit_vector.hpp', 'components/quad_bit_vector.hpp'))
        binary = tmp / name
        fcntl.flock(lock, fcntl.LOCK_EX)
        subprocess.run(['g++', *flags, '-I.', '-DWM_OPT_HEADER="' + str(header) + '"', 'test/benchmark/wavelet_matrix_opt.cpp', '-o', str(binary)], check=True)
        fcntl.flock(lock, fcntl.LOCK_UN)
        binaries[name] = binary
    for n, mode in [(200000, m) for m in [9, 10, 11, 12]] + [(500000, m) for m in [9, 10]]:
        samples = {name: [] for name in variants}
        checks = set()
        fcntl.flock(lock, fcntl.LOCK_EX)
        for trial in range(-1, 5):
            order = list(variants)
            rng.shuffle(order)
            for name in order:
                result = json.loads(subprocess.check_output([str(binaries[name]), str(n), '50000', str(mode), '0', 'count', '32', '81917']))
                checks.add(result['checksum'])
                if trial >= 0: samples[name].append(result['ms'])
        fcntl.flock(lock, fcntl.LOCK_UN)
        assert len(checks) == 1, (n, mode, checks)
        medians = {name: statistics.median(values) for name, values in samples.items()}
        row = dict(n=n, mode=mode, median_ms=medians, samples_ms=samples, checksum=checks.pop())
        report['results'].append(row)
        print(n, mode, medians, flush=True)
        (root / '.verify-helper/cache/wm_count_probe2.json').write_text(json.dumps(report, indent=2) + '\n')

